// Scooply's illustrations ("futuristic newspaper"): 3D objects printed in fine dithered pixels,
// generated by scripts/illustrations.ts into alpha masks. Each layer is tinted with a theme color,
// so the drawings follow light and dark. Moving layers get a motion class from globals.css,
// and all motion stops under prefers-reduced-motion.

import { SPRITES, type SpriteId } from './sprites'

const INK = {
  ink: 'var(--sc-ink)',
  muted: 'var(--sc-ink-4)',
  accent: 'var(--sc-accent)',
  gold: 'var(--sc-gold)',
  // halftone scale: solid steps from white through greys to black (ink is the darkest step)
  tone0: '#ffffff',
  tone1: '#dddcd7',
  tone2: '#b9b8b2',
  tone3: '#908f88',
  tone4: '#64635d',
  tone5: '#383733',
  shadow: '#cfcec8',
  // solid fill behind each object so it reads as a white object on any background
  paper: 'var(--sc-surface)',
  // masthead stripes: steps of ink, no hues
  tide: 'var(--sc-ink-3)',
  bloom: 'var(--sc-ink-2)',
  sun: 'var(--sc-ink-4)',
} as const

interface IllustrationProps {
  name: SpriteId
  /** Rendered width and height (any CSS length). Defaults to filling the parent's width. */
  size?: number | string
  /** Turn motion off (animated layers and scroll parallax), e.g. in dense lists. */
  still?: boolean
  /** Accessible name; omit for decorative use. */
  label?: string
  /** Recolor every ink layer (e.g. 'var(--sc-gold)' for decorative corners). */
  tint?: string
  className?: string
}

export default function Illustration({ name, size, still = false, label, tint, className = '' }: IllustrationProps) {
  const sprite = SPRITES[name]
  return (
    <span
      role={label ? 'img' : undefined}
      aria-label={label}
      aria-hidden={label ? undefined : true}
      className={`sc-illo relative inline-block shrink-0 ${still ? '' : 'sc-parallax'} ${className}`}
      style={{ width: size ?? '100%', aspectRatio: `${sprite.grid} / ${sprite.rows}` }}
    >
      {sprite.layers.map((layer, i) => {
        const motion = !still && 'motion' in layer ? `sc-illo-${layer.motion}` : ''
        const mask = `url(${layer.src}) 0 0 / 100% 100% no-repeat`
        return (
          <span
            key={i}
            className={`absolute inset-0 ${motion}`}
            style={{
              background: tint && (layer.ink as string) !== 'paper' ? tint : INK[layer.ink],
              WebkitMask: mask,
              mask,
              ...('delay' in layer ? { animationDelay: `${layer.delay}s` } : {}),
            }}
          />
        )
      })}
    </span>
  )
}
